import{_ as i,a0 as n,w as l,s as u,I as r,x as t,a1 as a,A as o,ao as d}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const T=JSON.parse('{"title":"Linux下如何过滤、分割以及合并 pcap 文件 | LCTT x X-CMD","titleTemplate":false,"description":"Linux下如何过滤、分割以及合并 pcap 文件 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux下如何过滤、分割以及合并 pcap 文件 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux下如何过滤、分割以及合并 pcap 文件 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/How to filter, split or merge pcap files on Linux","title":"Linux下如何过滤、分割以及合并 pcap 文件","tag":"201501","desc":""},"relativePath":"201501/How to filter, split or merge pcap files on Linux.md","filePath":"[post].md"}'),s={name:"201501/How to filter, split or merge pcap files on Linux.md"};function m(f,p,c,g,x,w){const e=n("Link");return l(),u("div",null,[p[27]||(p[27]=r("h1",{id:"linux下如何过滤、分割以及合并-pcap-文件",tabindex:"-1"},[t("Linux下如何过滤、分割以及合并 pcap 文件 "),r("a",{class:"header-anchor",href:"#linux下如何过滤、分割以及合并-pcap-文件","aria-label":"Permalink to “Linux下如何过滤、分割以及合并 pcap 文件”"},"​")],-1)),r("p",null,[p[2]||(p[2]=t("如果你是一个测试",-1)),a(e,{href:"http://xmodulo.com/how-to-compile-and-install-snort-from-source-code-on-ubuntu.html"},{default:o(()=>[...p[0]||(p[0]=[t("入侵侦测系统",-1)])]),_:1}),p[3]||(p[3]=t("或一些网络访问控制策略的网络管理员，那么你经常需要抓取数据包并在离线状态下分析这些文件。当需要保存捕获的数据包时，我们一般会存储为 libpcap 的数据包格式 pcap，这是一种被许多开源的嗅探工具以及捕包程序广泛使用的格式。如果 pcap 文件被用于入侵测试或离线分析的话，那么在将他们",-1)),a(e,{href:"http://xmodulo.com/how-to-capture-and-replay-network-traffic-on-linux.html"},{default:o(()=>[...p[1]||(p[1]=[t("注入",-1)])]),_:1}),p[4]||(p[4]=t("网络之前通常要先对 pcap 文件进行一些操作。",-1))]),p[28]||(p[28]=d(`<p><img src="https://farm8.staticflickr.com/7570/15425147404_a69f416673_c.jpg" alt=""></p><p>在这篇文章中，我将介绍一些操作 pcap 文件的工具，以及如何使用它们 。</p><h3 id="editcap-与-mergecap" tabindex="-1">Editcap 与 Mergecap### <a class="header-anchor" href="#editcap-与-mergecap" aria-label="Permalink to “Editcap 与 Mergecap###”">​</a></h3><p>Wireshark，是最受欢迎的 GUI 嗅探工具，实际上它带了一套非常有用的命令行工具集。其中包括 editcap 与 mergecap。editcap 是一个万能的 pcap 编辑器，它可以过滤并且能以多种方式来分割 pcap 文件。mergecap 可以将多个 pcap 文件合并为一个。 这篇文章就是基于这些 Wireshark 命令行工具的。</p><p>如果你已经安装过 Wireshark 了，那么这些工具已经在你的系统中了。如果还没装的话，那么我们接下来就安装 Wireshark 命令行工具。 需要注意的是，在基于 Debian 的发行版上我们可以不用安装 Wireshark GUI 而仅安装命令行工具，但是在 Red Hat 及 基于它的发行版中则需要安装整个 Wireshark 包。</p><p><strong>Debian, Ubuntu 或 Linux Mint</strong></p><pre><code>$ sudo apt-get install wireshark-common
</code></pre><p><strong>Fedora, CentOS 或 RHEL</strong></p><pre><code>$ sudo yum install wireshark
</code></pre><p>当安装好工具后， 就可以开始使用 editca 与 mergecap 了。</p><h3 id="pcap-文件过滤" tabindex="-1">pcap 文件过滤### <a class="header-anchor" href="#pcap-文件过滤" aria-label="Permalink to “pcap 文件过滤###”">​</a></h3><p>通过 editcap， 我们能以很多不同的规则来过滤 pcap 文件中的内容，并且将过滤结果保存到新文件中。</p><p>首先，以“起止时间”来过滤 pcap 文件。 &quot; - A &lt; start-time &gt; 和 &quot; - B &lt; end-time &gt; 选项可以过滤出在这个时间段到达的数据包（如，从 2:30 ～ 2:35）。时间的格式为 “ YYYY-MM-DD HH:MM:SS&quot;。</p><pre><code>$ editcap -A &#39;2014-12-10 10:11:01&#39; -B &#39;2014-12-10 10:21:01&#39; input.pcap output.pcap 
</code></pre><p>也可以从某个文件中提取指定的 N 个包。下面的命令行从 input.pcap 文件中提取100个包（从 401 到 500）并将它们保存到 output.pcap 中：</p><pre><code>$ editcap input.pcap output.pcap 401-500
</code></pre><p>使用 &quot;-D &lt; dup-window &gt;&quot; （dup-window可以看成是对比的窗口大小，仅与此范围内的包进行对比）选项可以提取出重复包。每个包都依次与它之前的 &lt; dup-window &gt; -1 个包对比长度与MD5值，如果有匹配的则丢弃。</p><pre><code>$ editcap -D 10 input.pcap output.pcap
</code></pre><blockquote><p>遍历了 37568 个包, 在 10 窗口内重复的包仅有一个，并丢弃。</p></blockquote><p>也可以将 &lt; dup-window &gt; 定义成时间间隔。使用&quot;-w &lt; dup-time-window &gt;&quot;选项，对比&lt; dup-time-window &gt; 时间内到达的包。</p><pre><code>$ editcap -w 0.5 input.pcap output.pcap 
</code></pre><blockquote><p>检索了 50000 个包, 以0.5s作为重复窗口，未找到重复包。</p></blockquote><p>###分割 pcap 文件###</p><p>当需要将一个大的 pcap 文件分割成多个小文件时，editcap 也能起很大的作用。</p><p>将一个 pcap 文件分割成数据包数目相同的多个文件</p><pre><code>$ editcap -c &lt;packets-per-file&gt; &lt;input-pcap-file&gt; &lt;output-prefix&gt; 
</code></pre><p>输出的每个文件有相同的包数量，以 &lt; output-prefix &gt;-NNNN的形式命名。</p><p>以时间间隔分割 pcap 文件</p><pre><code>$ editcap -i &lt;seconds-per-file&gt; &lt;input-pcap-file&gt; &lt;output-prefix&gt; 
</code></pre><p>###合并 pcap 文件###</p><p>如果想要将多个文件合并成一个，用 mergecap 就很方便。</p><p>当合并多个文件时，mergecap 默认将内部的数据包以时间先后来排序。</p><pre><code>$ mergecap -w output.pcap input.pcap input2.pcap [input3.pcap . . .]
</code></pre><p>如果要忽略时间戳，仅仅想以命令行中的顺序来合并文件，那么使用 -a 选项即可。</p><p>例如，下列命令会将 input.pcap 文件的内容写入到 output.pcap, 并且将 input2.pcap 的内容追加在后面。</p><pre><code>$ mergecap -a -w output.pcap input.pcap input2.pcap 
</code></pre><p>###总结###</p>`,37)),r("p",null,[p[9]||(p[9]=t("在这篇指导中，我演示了多个 editcap、 mergecap 操作 pcap 文件的例子。除此之外，还有其它的相关工具，如 ",-1)),a(e,{href:"https://www.wireshark.org/docs/man-pages/reordercap.html"},{default:o(()=>[...p[5]||(p[5]=[t("reordercap",-1)])]),_:1}),p[10]||(p[10]=t("用于将数据包重新排序，",-1)),a(e,{href:"https://www.wireshark.org/docs/man-pages/text2pcap.html"},{default:o(()=>[...p[6]||(p[6]=[t("text2pcap",-1)])]),_:1}),p[11]||(p[11]=t(" 用于将 pcap 文件转换为文本格式， ",-1)),a(e,{href:"https://github.com/isginf/pcap-diff"},{default:o(()=>[...p[7]||(p[7]=[t("pcap-diff",-1)])]),_:1}),p[12]||(p[12]=t("用于比较 pcap 文件的异同，等等。当进行网络入侵测试及解决网络问题时，这些工具与",-1)),a(e,{href:"http://xmodulo.com/how-to-capture-and-replay-network-traffic-on-linux.html"},{default:o(()=>[...p[8]||(p[8]=[t("包注入工具",-1)])]),_:1}),p[13]||(p[13]=t("非常实用，所以最好了解他们。",-1))]),p[29]||(p[29]=r("p",null,"你是否使用过 pcap 工具？ 如果用过的话，你用它来做过什么呢？",-1)),p[30]||(p[30]=r("hr",null,null,-1)),r("p",null,[p[15]||(p[15]=t("via: ",-1)),a(e,{href:"http://xmodulo.com/filter-split-merge-pcap-linux.html"},{default:o(()=>[...p[14]||(p[14]=[t("http://xmodulo.com/filter-split-merge-pcap-linux.html",-1)])]),_:1})]),r("p",null,[p[19]||(p[19]=t("作者：",-1)),a(e,{href:"http://xmodulo.com/author/nanni"},{default:o(()=>[...p[16]||(p[16]=[t("Dan Nanni",-1)])]),_:1}),p[20]||(p[20]=t(" 译者：",-1)),a(e,{href:"https://github.com/SPccman"},{default:o(()=>[...p[17]||(p[17]=[t("SPccman",-1)])]),_:1}),p[21]||(p[21]=t(" 校对：",-1)),a(e,{href:"https://github.com/wxy"},{default:o(()=>[...p[18]||(p[18]=[t("wxy",-1)])]),_:1})]),r("p",null,[p[24]||(p[24]=t("本文由 ",-1)),a(e,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...p[22]||(p[22]=[t("LCTT",-1)])]),_:1}),p[25]||(p[25]=t(" 原创翻译，",-1)),a(e,{href:"http://linux.cn/"},{default:o(()=>[...p[23]||(p[23]=[t("Linux中国",-1)])]),_:1}),p[26]||(p[26]=t(" 荣誉推出",-1))])])}const b=i(s,[["render",m]]);export{T as __pageData,b as default};
